USE sccmgpc;
CREATE TABLE IF NOT EXISTS distritos(id_distrito INT AUTO_INCREMENT PRIMARY KEY,numero_distrito INT NOT NULL UNIQUE,nombre_distrito VARCHAR(100) NOT NULL) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS usuarios(id_usuario INT AUTO_INCREMENT PRIMARY KEY,nombre_usuario VARCHAR(60) NOT NULL UNIQUE,clave_hash VARCHAR(255) NOT NULL,nombre_completo VARCHAR(160) NOT NULL,perfil ENUM('CONTROL_GENERAL','DEOEYG','DISTRITO','CONSULTA') NOT NULL,id_distrito INT NULL,activo TINYINT(1) NOT NULL DEFAULT 1,debe_cambiar_clave TINYINT(1) NOT NULL DEFAULT 1,fecha_creacion TIMESTAMP DEFAULT CURRENT_TIMESTAMP,CONSTRAINT fk_usuario_distrito FOREIGN KEY(id_distrito) REFERENCES distritos(id_distrito)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS casos_actualizacion(id_caso INT AUTO_INCREMENT PRIMARY KEY,uuid_registro CHAR(32) NOT NULL UNIQUE,folio VARCHAR(60) UNIQUE,id_distrito INT NOT NULL,id_usuario_registro INT NOT NULL,id_seccxut INT NULL,clave_demarcacion INT NULL,nombre_demarcacion VARCHAR(160),clave_ut VARCHAR(30),nombre_ut VARCHAR(220),secciones_c TEXT,secciones_p TEXT,nombre_solicitante VARCHAR(220),tipo_solicitante VARCHAR(100),correo VARCHAR(160),telefono VARCHAR(60),fecha_recepcion DATE,medio_recepcion VARCHAR(100),descripcion_solicitud TEXT,tipo_caso VARCHAR(60),analisis_clasificacion TEXT,planeacion TEXT,trabajo_campo TEXT,requiere_encuesta TINYINT(1) DEFAULT 0,modelo_encuesta VARCHAR(80),encuestas_aplicadas INT DEFAULT 0,respuestas_favor INT DEFAULT 0,respuestas_contra INT DEFAULT 0,actualizacion_externa TEXT,propuesta_distrital TEXT,revision_tecnica TEXT,resultado_tecnico VARCHAR(120),cierre_expediente TEXT,estado VARCHAR(60) NOT NULL DEFAULT 'REGISTRADO',fase_actual TINYINT NOT NULL DEFAULT 1,sin_casos TINYINT(1) NOT NULL DEFAULT 0,fecha_registro TIMESTAMP DEFAULT CURRENT_TIMESTAMP,fecha_actualizacion TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,fecha_cierre DATETIME NULL,INDEX idx_caso_distrito(id_distrito),INDEX idx_caso_seccxut(id_seccxut),CONSTRAINT fk_caso_distrito FOREIGN KEY(id_distrito) REFERENCES distritos(id_distrito),CONSTRAINT fk_caso_usuario FOREIGN KEY(id_usuario_registro) REFERENCES usuarios(id_usuario)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS archivos_caso(id_archivo BIGINT AUTO_INCREMENT PRIMARY KEY,id_caso INT NOT NULL,categoria VARCHAR(100) NOT NULL,nombre_original VARCHAR(255) NOT NULL,tipo_mime VARCHAR(150),tamano_bytes BIGINT,hash_archivo CHAR(64),contenido LONGBLOB NOT NULL,id_usuario_carga INT NOT NULL,fecha_carga TIMESTAMP DEFAULT CURRENT_TIMESTAMP,INDEX idx_archivo_caso(id_caso),CONSTRAINT fk_archivo_caso FOREIGN KEY(id_caso) REFERENCES casos_actualizacion(id_caso) ON DELETE CASCADE,CONSTRAINT fk_archivo_usuario FOREIGN KEY(id_usuario_carga) REFERENCES usuarios(id_usuario)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS bitacora_sistema(id_bitacora BIGINT AUTO_INCREMENT PRIMARY KEY,id_usuario INT NULL,id_caso INT NULL,accion VARCHAR(120) NOT NULL,detalle TEXT,direccion_ip VARCHAR(60),fecha_movimiento TIMESTAMP DEFAULT CURRENT_TIMESTAMP,INDEX idx_bitacora_caso(id_caso)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
